import java.util.*;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> edades = new HashMap<>();
        edades.put("Ana", 25);
        edades.put("Luis", 30);
        edades.put("Maria", 22);

        int edadLuis = Optional.ofNullable(edades.get("Luis"))
            .orElse(-1);

        int edadPedro = Optional.ofNullable(edades.get("Pedro"))
            .orElse(-1);

        System.out.println("Age of Luis: " + edadLuis);
        System.out.println("Age of Pedro: " + edadPedro);
    }
}

