import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        Optional<String> texto1 = Optional.of("hola mundo");
        Optional<String> texto2 = Optional.of("");
        Optional<String> texto3 = Optional.empty();

        String resultado1 = texto1
            .filter(s -> !s.isEmpty())
            .map(s -> s.toUpperCase())
            .map(s -> s + "!")
            .orElseThrow(() -> new RuntimeException("empty or null text"));

        try {
            String resultado2 = texto2
                .filter(s -> !s.isEmpty())
                .map(s -> s.toUpperCase())
                .map(s -> s + "!")
                .orElseThrow(() -> new RuntimeException("empty or null text"));
            System.out.println("Text2: " + resultado2);
        } catch (RuntimeException e) {
            System.out.println("Text2 error: " + e.getMessage());
        }

        try {
            String resultado3 = texto3
                .filter(s -> !s.isEmpty())
                .map(s -> s.toUpperCase())
                .map(s -> s + "!")
                .orElseThrow(() -> new RuntimeException("empty or null text"));
            System.out.println("Text3: " + resultado3);
        } catch (RuntimeException e) {
            System.out.println("Text3 error: " + e.getMessage());
        }

        System.out.println("Text1: " + resultado1);
    }
}

