import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Optional<String>> opcionales = Arrays.asList(
            Optional.of("Java"),
            Optional.empty(),
            Optional.of(""),
            Optional.of("Stream"),
            Optional.empty(),
            Optional.of("Optional"),
            Optional.of("null"),
            Optional.empty()
        );

        long cantidad = opcionales.stream()
            .filter(Optional::isPresent)
            .map(Optional::get)
            .filter(s -> !s.isEmpty())
            .filter(s -> !s.equals("null"))
            .map(String::toUpperCase)
            .peek(System.out::println)
            .count();

        System.out.println("Total: " + cantidad);
    }
}
